from dataclasses import dataclass, field
import json
from urllib.parse import parse_qs
import random
from typing import TypeGuard
import web

from infogami.utils import delegate
from infogami.utils.view import render_template, public
from infogami.infobase import client, common

from openlibrary.accounts import get_current_user
from openlibrary.core import formats, cache
from openlibrary.core.lists.model import List, SeedDict, SeedSubjectString
import openlibrary.core.helpers as h
from openlibrary.i18n import gettext as _
from openlibrary.plugins.upstream.addbook import safe_seeother
from openlibrary.utils import dateutil, olid_to_key
from openlibrary.plugins.upstream import spamcheck, utils
from openlibrary.plugins.upstream.account import MyBooksTemplate
from openlibrary.plugins.worksearch import subjects
from openlibrary.coverstore.code import render_list_preview_image


def is_seed_subject_string(seed: str) -> TypeGuard[SeedSubjectString]:
    return seed.startswith(('subject:', 'place:', 'person:', 'time:'))


def subject_key_to_seed(key: str) -> SeedSubjectString:
    seed = key.split('/')[-1]
    if not is_seed_subject_string(seed):
        seed = f'subject:{seed}'
    return SeedSubjectString(seed.replace(',', '_').replace('__', '_'))


@dataclass
class ListRecord:
    key: str | None = None
    name: str = ''
    description: str = ''
    seeds: list[SeedDict | SeedSubjectString] = field(default_factory=list)

    @staticmethod
    def normalize_input_seed(seed: SeedDict | str) -> SeedDict | SeedSubjectString:
        if isinstance(seed, str):
            if seed.startswith('/subjects/'):
                return subject_key_to_seed(seed)
            if is_seed_subject_string(seed):
                return seed
            return {'key': seed if seed.startswith('/') else olid_to_key(seed)}
        if seed['key'].startswith('/subjects/'):
            return subject_key_to_seed(seed['key'])
        if is_seed_subject_string(seed['key']):
            return SeedSubjectString(seed['key'])
        return seed

    @staticmethod
    def from_input():
        DEFAULTS = {
            'key': None,
            'name': '',
            'description': '',
            'seeds': [],
        }
        if data := web.data():
            # If the requests has data, parse it and use it to populate the list
            if web.ctx.env.get('CONTENT_TYPE') == 'application/json':
                i = {} | DEFAULTS | json.loads(data)
            else:
                form_data = {
                    # By default all the values are lists
                    k: v[0]
                    for k, v in parse_qs(bytes.decode(data)).items()
                }
                i = {} | DEFAULTS | utils.unflatten(form_data)
        else:
            # Otherwise read from the query string
            i = utils.unflatten(web.input(**DEFAULTS))

        normalized_seeds = [
            ListRecord.normalize_input_seed(seed)
            for seed_list in i['seeds']
            for seed in (
                seed_list.split(',') if isinstance(seed_list, str) else [seed_list]
            )
        ]
        normalized_seeds = [
